import json, math, sys
d = json.load(open(sys.argv[1]))
recs, base_ex = d["recs"], d["excluded"]

def best_v(p, km):
    return sum(v*S/(km+S) for S,v in p)/sum((S/(km+S))**2 for S,v in p)
def ssr(p, V, km):
    return sum((v-V*S/(km+S))**2 for S,v in p)
def golden(f,a,b):
    gr=(math.sqrt(5)-1)/2; c=b-gr*(b-a); e=a+gr*(b-a); fc,fe=f(c),f(e)
    for _ in range(200):
        if fc<fe: b,e,fe=e,c,fc; c=b-gr*(b-a); fc=f(c)
        else: a,c,fc=c,e,fe; e=a+gr*(b-a); fe=f(e)
    return (a+b)/2
def fit(p, V=None):
    if V is None:
        g=lambda lk: ssr(p,best_v(p,math.exp(lk)),math.exp(lk))
    else:
        g=lambda lk: ssr(p,V,math.exp(lk))
    grid=[math.log(10**(x/50.0)) for x in range(-100,150)]
    lk0=min(grid,key=g); lk=golden(g,lk0-0.1,lk0+0.1); km=math.exp(lk)
    return (best_v(p,km) if V is None else V), km
def pts(cond, ex):
    return [(r["S"], r["v"]) for sid,r in recs.items() if r["cond"]==cond and sid not in ex]

def run(label, ex):
    f={}
    for c in ["C2","C4","C5","C6","C7"]:
        f[c]=fit(pts(c,ex))
    f["C1"]=fit(pts("C1",ex),f["C4"][0]); f["C3"]=fit(pts("C3",ex),f["C7"][0])
    print(label, " ".join("%s:V%.3f/K%.1f"%(c,f[c][0],f[c][1]) for c in ["C1","C2","C3","C4","C5","C6","C7"]))

run("BASE", base_ex)
run("keep TV-0443", {k:v for k,v in base_ex.items() if k!="TV-0443"})
run("keep TV-0384", {k:v for k,v in base_ex.items() if k!="TV-0384"})
run("excl TV-0440 instead of TV-0287", {**{k:v for k,v in base_ex.items() if k!="TV-0287"}, "TV-0440":"x"})
run("keep TV-0494", {k:v for k,v in base_ex.items() if k!="TV-0494"})
run("excl TV-0508 (ignore retraction)", {**base_ex, "TV-0508":"x"})
run("excl TV-0329 (bubble)", {**base_ex, "TV-0329":"x"})
